export function initDemo({reset,showReminders}){
 const banner=document.createElement('section');banner.className='demo-banner';banner.innerHTML='<div><span class="demo-pill">ÅBEN DEMO</span><strong>Prøv et enklere overblik over jobsøgningen</strong><p>Du prøver fiktive oplysninger. Ændringer gemmes kun i denne fane. Brug ikke personlige oplysninger.</p></div><div class="demo-banner-actions"><button id="demo-try" class="primary">Prøv en påmindelse</button><button id="demo-feedback">Giv feedback</button><button id="demo-reset">Start forfra</button></div>';
 document.querySelector('main').prepend(banner);
 document.querySelector('#demo-try').addEventListener('click',showReminders);
 document.querySelector('#demo-reset').addEventListener('click',()=>{feedback.querySelector('form').reset();document.querySelector('#feedback-result').textContent='';document.querySelector('#feedback-copy').value='';document.querySelector('#feedback-copy').hidden=true;reset()});
 document.querySelector('#demo-feedback').addEventListener('click',()=>feedback.showModal());
 const about=document.createElement('section');about.className='demo-about';about.innerHTML='<div><h2>Et projekt, der starter i hverdagen</h2><p>Jeg er selv jobsøgende og bygger Mit joboverblik med AI som udviklingsværktøj. Målet er færre klik og bedre styr på ansøgninger, frister og næste skridt.</p><p>Prøv at planlægge opfølgning, give flere ansøgninger samme dato eller markere jobmessen som gennemført.</p></div><div><h3>Hvad kan du prøve her?</h3><p>Denne demo viser overblik, aktiviteter og påmindelser. Du kan prøve alle funktionerne uden login.</p><button id="demo-about-feedback">Hjælp med næste version →</button><button id="demo-privacy">Om data i demoen</button></div>';
 document.querySelector('footer').before(about);
 const feedback=document.createElement('dialog');feedback.id='feedback-dialog';feedback.innerHTML='<form id="feedback-form"><div class="modal-head"><div><div class="eyebrow">HJÆLP MED NÆSTE VERSION</div><h2>Hvad synes du om demoen?</h2></div><button type="button" id="feedback-close" class="icon-btn" aria-label="Luk feedback">×</button></div><label>Var det let at finde ud af?<select name="ease"><option value="Ikke besvaret">Vælg et svar (valgfrit)</option><option>Ja</option><option>Delvist</option><option>Nej</option></select></label><label>Hvad ville være mest nyttigt for dig?<textarea name="useful" rows="2" maxlength="1000" placeholder="Fx bedre overblik over frister…"></textarea></label><label>Hvad var svært, eller hvad mangler?<textarea name="missing" rows="3" maxlength="1500" placeholder="Skriv gerne helt konkret. Undlad personlige oplysninger."></textarea></label><p class="form-note">Feedback sendes ikke automatisk. Kopiér teksten og send den til personen, der delte demoen.</p><button type="submit" class="primary">Kopiér min feedback</button><p id="feedback-result" role="status"></p><textarea id="feedback-copy" rows="6" readonly hidden aria-label="Din feedback klar til at kopiere"></textarea></form>';
 document.body.append(feedback);document.querySelector('#feedback-close').addEventListener('click',()=>feedback.close());document.querySelector('#demo-about-feedback').addEventListener('click',()=>feedback.showModal());
 document.querySelector('#feedback-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;const message=`Feedback på Mit joboverblik – demo\n\nLet at finde ud af: ${f.elements.ease.value}\nMest nyttigt: ${f.elements.useful.value.trim()||'Ikke udfyldt'}\nSvært eller mangler: ${f.elements.missing.value.trim()||'Ikke udfyldt'}`;try{await navigator.clipboard.writeText(message);document.querySelector('#feedback-result').textContent='Kopieret. Send nu teksten til personen, der delte demoen.';}catch{const box=document.querySelector('#feedback-copy');box.hidden=false;box.value=message;box.focus();box.select();document.querySelector('#feedback-result').textContent='Markér og kopiér teksten nedenfor.';}});
 const privacy=document.createElement('dialog');privacy.innerHTML='<div class="notice-inner"><div class="eyebrow">OM DENNE DEMO</div><h2>Dine ændringer bliver i fanen</h2><p>Demoen er til at afprøve funktioner med fiktive oplysninger. Ændringer gemmes i fanens sessionslager og forsvinder, når fanen lukkes. Start forfra nulstiller prøveoplysningerne.</p><p>Demoen har ingen database til joboplysninger, ingen AI-kald. Feedback kopieres kun til din udklipsholder, når du vælger det. Demoen sender ikke feedback automatisk.</p><p>Der er ikke tilføjet analyseværktøjer eller reklametrackere i appkoden. Hostingudbyderen kan behandle tekniske besøgsoplysninger. Dette er en tidlig demo, ikke en færdig tjeneste til rigtige joboplysninger.</p><button id="privacy-close" class="primary">Luk</button></div>';
 document.body.append(privacy);document.querySelector('#demo-privacy').addEventListener('click',()=>privacy.showModal());privacy.querySelector('#privacy-close').addEventListener('click',()=>privacy.close());
}
